{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "The absolute oral bioavailability of 17-beclomethasone monopropionate, the active metabolite of beclomethasone dipropionate and a very close structural analogue of the query, was 41% (90% CI 31–54%) in healthy subjects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Nomegestrol acetate, a steroidal progestin, showed absolute oral bioavailability of 63.4% in healthy women, supporting high oral absorption for steroid scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Chlormadinone acetate, a halogenated steroid, had approximately 100% oral bioavailability in humans, indicating that such steroids can be essentially completely absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Cyproterone acetate, another halogenated steroid, had almost complete absolute bioavailability (88% of dose) in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Ursodeoxycholic acid showed 50% systemic availability in healthy subjects, providing another steroid example with oral bioavailability well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danazol in the fasted state had low absolute bioavailability (11 ± 5.2%), but this is a solubility/formulation-limited effect for a highly lipophilic steroid and is not representative of the more polar, hydroxylated query corticosteroid.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a halogenated corticosteroid closely related to beclomethasone/17-BMP. The closest analogue, 17-BMP, has absolute oral bioavailability of 41% in humans, and multiple other steroids (NOMAC 63%, chlormadinone acetate ~100%, cyproterone acetate 88%) support F ≥ 20%. The only low values come from danazol in the fasted state, which is solubility-limited and not applicable to the more polar query. Therefore the prediction is high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule; reliance on close analogues.",
    "The effect of first-pass metabolism on the free 17,21-dihydroxy steroid side chain is not directly measured.",
    "Formulation and fed/fasted conditions for the query are unspecified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

